//! Runtime of the fixture's mock distribution (M6-T1).
//!
//! This is the normal-library half of the mock distribution; the proc-macro
//! half lives in `xbin-mock-distro`. It owns the process-global [`MockSystem`]
//! that stands in for the project's shared-memory regions and re-exports the
//! in-tree runtime items the generated code refers to, so an application only
//! depends on this crate and the generated `ipc-types`. The `RticSwTask` trait
//! the receivers implement is generated by the software pass bound in
//! `xbin-mock-distro` (M6.5-T5), not defined here.
//!
//! Because the system is process-global, the three fixture applications
//! expanded into one process (the M6-T1 runtime harness) share the same
//! regions while each gets the backend handle of its own core through
//! [`backend_for`].

use std::sync::LazyLock;

pub use rticx_xbin_mock::{MockBackend, MockSystem};
pub use rticx_xbin_rt as xbin_rt;

/// The fixture project's IPC regions, in process memory.
///
/// The regions are declared with the same `(source, target)` pairs and sizes
/// as `rticx.toml`; the mock ignores the declared addresses and uses the
/// backing array's own.
pub fn system() -> &'static MockSystem {
    static SYSTEM: LazyLock<MockSystem> = LazyLock::new(|| {
        let mut system = MockSystem::new();
        system
            .add_region(0, 1, 4096)
            .expect("the fixture declares the `0->1` region");
        system
            .add_region(2, 1, 4096)
            .expect("the fixture declares the `2->1` region");
        system
    });
    &SYSTEM
}

/// Returns the backend handle of global core `core`.
pub fn backend_for(core: u32) -> MockBackend {
    system().backend(core)
}
